export const getResetSessionUrl = (id: string, params?: ResetSessionParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/ingest/${id}?${stringifiedParams}`
    : `/api/ingest/${id}`;
};

/**
 * @summary Delete a session's summary/event/chunk docs so it can be re-ingested
 */
export const resetSession = async (
  id: string,
  params?: ResetSessionParams,
  options?: Parameters<typeof customFetch>[1],
): Promise<SessionResetResult> => {
  return customFetch<SessionResetResult>(getResetSessionUrl(id, params), {
    ...options,
    method: "DELETE",
  });
};

export const getResetSessionMutationKey = () => ["resetSession"] as const;

export const getResetSessionMutationOptions = <
  TError = ErrorType<ResetSession400 | ResetSession500>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof resetSession>>,
    TError,
    ResetSessionMutationVariables,
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationOptions<
  Awaited<ReturnType<typeof resetSession>>,
  TError,
  ResetSessionMutationVariables,
  TContext
> => {
  const mutationKey = getResetSessionMutationKey();
  const { mutation: mutationOptions, request: requestOptions } = options
    ? options.mutation && "mutationKey" in options.mutation && options.mutation.mutationKey
      ? options
      : { ...options, mutation: { ...options.mutation, mutationKey } }
    : { mutation: { mutationKey }, request: undefined };

  const mutationFn: MutationFunction<
    Awaited<ReturnType<typeof resetSession>>,
    ResetSessionMutationVariables
  > = (props) => {
    const { id, params } = props ?? {};

    return resetSession(id, params, requestOptions);
  };

  return { mutationFn, ...mutationOptions };
};

export type ResetSessionMutationResult = NonNullable<Awaited<ReturnType<typeof resetSession>>>;

export type ResetSessionMutationError = ErrorType<ResetSession400 | ResetSession500>;
export type ResetSessionMutationVariables = { id: string; params?: ResetSessionParams };

/** @summary Delete a session's summary/event/chunk docs so it can be re-ingested */
